const MAX_NAME_LENGTH = 255;

/**
 * Make a user-supplied filename safe to store and display. The name is only
 * ever metadata — storage keys are generated by the server, so this is about
 * display hygiene, not path safety.
 */
export function sanitizeFileName(raw: string) {
  let name = raw
    .normalize("NFC")
    // Drop any client path ("C:\fakepath\x.png", "../../x.png").
    .split(/[\\/]/)
    .pop()!
    // Control characters and bidi overrides (used to disguise extensions).
    .replace(/[\u0000-\u001f\u007f\u202a-\u202e\u2066-\u2069]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  if (!name || name === "." || name === "..") name = "untitled";

  if (name.length > MAX_NAME_LENGTH) {
    const ext = getExtension(name);
    const keep = MAX_NAME_LENGTH - (ext ? ext.length + 1 : 0);
    name = ext ? `${name.slice(0, keep)}.${ext}` : name.slice(0, MAX_NAME_LENGTH);
  }

  return name;
}

/** Lowercase extension without the dot, or "" when absent/implausible. */
export function getExtension(name: string) {
  const match = /\.([a-z0-9]{1,10})$/i.exec(name);
  return match ? match[1].toLowerCase() : "";
}
